$id = [Security.Principal.WindowsIdentity]::GetCurrent()
$isAdmin = (New-Object Security.Principal.WindowsPrincipal($id)).IsInRole([Security.Principal.WindowsBuiltInRole]::Administrator)
if (-not $isAdmin) {
    Say 'FEHLER: Bitte in der Clientverwaltung als "System" ausfuehren.'
    exit 1
}

Say 'Install-PatchPilot-Clientverwaltung V0.10.4 gestartet.'

# Laufenden Updatelauf nicht stoeren (Dateien wuerden mitten im Lauf ausgetauscht)
$runTasks = @('PatchPilot-Friday', 'PatchPilot-Boot', 'PatchPilot-Remind', 'PatchPilot-Preload', 'PatchPilot-Manual', 'PatchPilot-Manual-Shutdown', 'PatchPilot-Fernstart', 'PatchPilot-Direct')
$busy = @(Get-ScheduledTask -TaskPath '\' -ErrorAction SilentlyContinue | Where-Object { $runTasks -contains $_.TaskName -and $_.State -eq 'Running' })
if ($busy.Count -gt 0) {
    Say ('Ein Patch-Pilot-Updatelauf laeuft gerade (' + (($busy | ForEach-Object { $_.TaskName }) -join ', ') + '). Nichts installiert.')
    Say 'Ergebnis: Updatelauf aktiv, bitte spaeter erneut ausfuehren (Code 4).'
    exit 4
}

$stage = Join-Path $env:SystemRoot ('Temp\PatchPilot_Setup_' + [guid]::NewGuid().ToString('N'))
$code = 3
try {
    try {
        New-Item -ItemType Directory -Path $stage -Force | Out-Null
        foreach ($f in $Files) {
            $raw = [Convert]::FromBase64String(($f.Data -replace '\s', ''))
            $in = New-Object IO.MemoryStream(, $raw)
            $gz = New-Object IO.Compression.GZipStream($in, [IO.Compression.CompressionMode]::Decompress)
            $out = New-Object IO.MemoryStream
            $gz.CopyTo($out)
            $gz.Dispose(); $in.Dispose()
            $bytes = $out.ToArray(); $out.Dispose()

            $sha = [Security.Cryptography.SHA256]::Create()
            $hash = ([BitConverter]::ToString($sha.ComputeHash($bytes))) -replace '-', ''
            $sha.Dispose()
            if ($hash -ne $f.Sha256) {
                Say ('FEHLER: Pruefsumme falsch bei ' + $f.Name + '. Skript in der Clientverwaltung neu einfuegen.')
                $code = 11
                throw 'Pruefsumme'
            }
            [IO.File]::WriteAllBytes((Join-Path $stage $f.Name), $bytes)
        }
        Say ('Entpackt und geprueft: ' + $Files.Count + ' Dateien.')
    } catch {
        if ($code -ne 11) {
            Say ('FEHLER beim Entpacken: ' + $_.Exception.Message)
            $code = 12
        }
        throw
    }

    $installer = Join-Path $stage $Files[0].Name
    $sysDir = 'System32'
    if ([Environment]::Is64BitOperatingSystem -and -not [Environment]::Is64BitProcess) { $sysDir = 'Sysnative' }  # 64-Bit-PowerShell erzwingen
    $ps = Join-Path $env:SystemRoot ($sysDir + '\WindowsPowerShell\v1.0\powershell.exe')
    Say 'Starte Installer...'
    & $ps -NoProfile -ExecutionPolicy Bypass -File $installer -SourceDir $stage
    $code = $LASTEXITCODE
    if ($null -eq $code) { $code = 3 }
} catch {
    if ($code -eq 3) { Say ('FEHLER: ' + $_.Exception.Message) }
} finally {
    if (Test-Path -LiteralPath $stage) {
        Remove-Item -LiteralPath $stage -Recurse -Force -ErrorAction SilentlyContinue
    }
}

switch ($code) {
    0       { Say 'Ergebnis: Patch Pilot 0.10.4 installiert (Code 0).' }
    1       { Say 'Ergebnis: keine Administratorrechte (Code 1).' }
    2       { Say 'Ergebnis: Paketdateien oder Zeiten ungueltig (Code 2).' }
    11      { Say 'Ergebnis: eingebettete Datei beschaedigt, nichts installiert (Code 11).' }
    12      { Say 'Ergebnis: Entpacken fehlgeschlagen, nichts installiert (Code 12).' }
    default { Say ("Ergebnis: Fehler bei der Installation (Code $code). Log: C:\Fernwartung\PatchPilot\Logs") }
}
exit $code
